import os,sys,time,hashlib,base64,zlib,json,subprocess,signal,fcntl,importlib.metadata
from pathlib import Path
os.environ["KERAS_BACKEND"]="tensorflow"
os.environ.setdefault("TF_CPP_MIN_LOG_LEVEL","2")
os.environ.setdefault("TF_DETERMINISTIC_OPS","1")
os.environ.setdefault("CUBLAS_WORKSPACE_CONFIG",":4096:8")
os.environ.setdefault("TOKENIZERS_PARALLELISM","false")
os.environ.setdefault("PYTHONHASHSEED","42")

def _environment():
    required={"numpy":"2.1.3","pandas":"2.3.3","scipy":"1.15.3","scikit-learn":"1.6.1"}
    if OPTIONS['MODE']=='RUN':required.update({"tensorflow":"2.20.0","keras":"3.13.2"})
    missing=[]
    for package,version in required.items():
        try:current=importlib.metadata.version(package)
        except importlib.metadata.PackageNotFoundError:current=None
        if current!=version:missing.append(f'{package}=={version}')
    try:importlib.metadata.version('matplotlib')
    except importlib.metadata.PackageNotFoundError:missing.append('matplotlib')
    if missing:
        if not OPTIONS['INSTALL_MATCHING_ENVIRONMENT']:
            raise RuntimeError('Missing pinned package versions: '+', '.join(missing))
        print('Installing/reconciling packages before fresh worker:',', '.join(missing),flush=True)
        subprocess.run([sys.executable,'-m','pip','install','--quiet','--disable-pip-version-check',*missing],check=True)
    for package,version in required.items():
        if importlib.metadata.version(package)!=version:
            raise RuntimeError('Pinned environment differs after installation: '+package)

def _run():
    if OPTIONS['MODE'] not in ('RUN','REPORT_ONLY'):raise ValueError('Invalid MODE')
    allowed=[42,2026,3407,123,777]
    if any(s not in allowed for s in OPTIONS['RUN_SEEDS']) or len(set(OPTIONS['RUN_SEEDS']))!=len(OPTIONS['RUN_SEEDS']):
        raise ValueError('RUN_SEEDS must be a subset of 42, 2026, 3407, 123, 777, without repetition')
    _environment()
    root=Path(OPTIONS['OUTPUT_DIR']);root.mkdir(parents=True,exist_ok=True)
    with (root/'.onecell.lock').open('a+') as lock:
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:raise RuntimeError('This output folder already has an active one-cell run')
        runtime=root/'runtime';runtime.mkdir(exist_ok=True)
        for name,item in PAYLOAD.items():
            content=zlib.decompress(base64.b64decode(item['payload']))
            if hashlib.sha256(content).hexdigest()!=item['sha256']:
                raise RuntimeError('Embedded source checksum changed: '+name)
            dest=runtime/name
            if dest.is_file() and hashlib.sha256(dest.read_bytes()).hexdigest()!=item['sha256']:
                raise RuntimeError('Existing runtime source conflicts. Use another OUTPUT_DIR or recover original')
            temporary=dest.with_suffix('.tmp');temporary.write_bytes(content);os.replace(temporary,dest)
        args=dict(OPTIONS,STARTED_AT=time.time())
        path=runtime/'options.json';path.write_text(json.dumps(args,indent=2),encoding='utf-8')
        env=os.environ.copy();env['PYTHONUNBUFFERED']='1'
        process=subprocess.Popen([sys.executable,str(runtime/'fusion_six_driver.py'),'--settings',str(path)],
            stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1,env=env,start_new_session=True)
        try:
            for line in process.stdout:print(line,end='',flush=True)
            code=process.wait()
        except KeyboardInterrupt:
            os.killpg(process.pid,signal.SIGINT)
            print('Requested clean pause: complete-epoch checkpoints and results are kept.',flush=True)
            for line in process.stdout:print(line,end='',flush=True)
            code=process.wait()
        print('COMPLETE NATIVE FOLDER:',root,flush=True)
        print('SEPARATE RESULTS-ONLY ZIP:',root.parent/(root.name+'_RESULTS_ONLY.zip'),flush=True)
        if code not in (0,75):
            raise RuntimeError('See the specific traceback/log above and RUN_ERROR.json. Completed fits are preserved.')
        if code==75:print('PARTIAL: archive COMPLETE native folder as a Kaggle Dataset and rerun this cell to finish all five seeds.',flush=True)
_run()
